metrics.workdir_dsl:
workspace "Bookshop" "A simple online bookshop" {

    model {
        customer = person "Customer" "A customer of the bookshop"

        bookshop = softwareSystem "Bookshop" "An online bookshop" {
            webapp = container "Web Application" "Serves the bookshop website" "React"
            api = container "API" "Provides the bookshop API" "Node.js"
            db = container "Database" "Stores book and order data" "PostgreSQL"
        }

        payment = softwareSystem "Payment Provider" "Processes payments" "External"

        customer -> webapp "Browses books and places orders" "HTTPS"
        webapp -> api "Makes API calls" "HTTPS/JSON"
        api -> db "Reads and writes book and order data" "SQL"
        api -> payment "Submits payment requests" "HTTPS/JSON"
    }

    views {
        systemContext bookshop "SystemContext" "The system context view of the Bookshop" {
            include *
            autoLayout
        }

        container bookshop "Containers" "The container view of the Bookshop" {
            include *
            autoLayout
        }

        styles {
            element "Person" {
                shape Person
                background #08427B
                color #ffffff
            }
            element "Software System" {
                background #1168BD
                color #ffffff
            }
            element "External" {
                background #999999
                color #ffffff
            }
            element "Container" {
                background #438DD5
                color #ffffff
            }
            element "Database" {
                shape Cylinder
            }
            relationship "Relationship" {
                routing Orthogonal
            }
        }
    }

    configuration {
        scope softwaresystem
    }
}
